static bool vu_rem_mem_reg ( VuDev * dev , VhostUserMsg * vmsg ) { int i , j ; bool found = false ; VuDevRegion shadow_regions [ VHOST_USER_MAX_RAM_SLOTS ] { } ; ; VhostUserMemoryRegion m = vmsg -> payload . memreg . region , * msg_region = & m ; DPRINT ( "Removing region:\n" ) ; DPRINT ( "    guest_phys_addr: 0x%016" PRIx64 "\n" , msg_region -> guest_phys_addr ) ; DPRINT ( "    memory_size:     0x%016" PRIx64 "\n" , msg_region -> memory_size ) ; DPRINT ( "    userspace_addr   0x%016" PRIx64 "\n" , msg_region -> userspace_addr ) ; DPRINT ( "    mmap_offset      0x%016" PRIx64 "\n" , msg_region -> mmap_offset ) ; for ( i = 0 , j = 0 ; i < dev -> nregions ; i ++ ) { if ( ! reg_equal ( & dev -> regions [ i ] , msg_region ) ) { shadow_regions [ j ] . gpa = dev -> regions [ i ] . gpa ; shadow_regions [ j ] . size = dev -> regions [ i ] . size ; shadow_regions [ j ] . qva = dev -> regions [ i ] . qva ; shadow_regions [ j ] . mmap_addr = dev -> regions [ i ] . mmap_addr ; shadow_regions [ j ] . mmap_offset = dev -> regions [ i ] . mmap_offset ; j ++ ; } else { found = true ; VuDevRegion * r = & dev -> regions [ i ] ; void * m = ( void * ) ( uintptr_t ) r -> mmap_addr ; } } if ( found ) { memcpy ( dev -> regions , shadow_regions , sizeof ( VuDevRegion ) * VHOST_USER_MAX_RAM_SLOTS ) ; DPRINT ( "Successfully removed a region\n" ) ; dev -> nregions -- ; vmsg_set_reply_u64 ( vmsg , 0 ) ; } else { vu_panic ( dev , "Specified region not found\n" ) ; } return true ; } 